import re, sys, os
W = sys.argv[1]
pat_assign = re.compile(r'=\s*(?:__)?skb_header_pointer(?:_with_crop)?\s*\(')
sites = []
with open(os.path.join(W,'shp_s03.txt')) as f:
    for line in f:
        path, ln, rest = line.split(':',2)
        sites.append((path,int(ln),rest.rstrip()))
# Find sites where result is assigned to a var, and check next ~8 lines for NULL check or immediate deref
suspicious = []
by_file = {}
for path, ln, rest in sites:
    by_file.setdefault(path, []).append((ln, rest))
for path, lst in by_file.items():
    try:
        lines = open(path, errors='replace').read().splitlines()
    except Exception:
        continue
    for ln, rest in lst:
        if not pat_assign.search(rest):
            continue
        window = ' '.join(lines[ln:ln+8])  # ln is 1-based; lines[ln] is the next line
        has_nullchk = re.search(r'\b'+re.escape('if') + r'\s*\(\s*!\s*\w+', window) or re.search(r'==\s*NULL', window) or re.search(r'IS_ERR', window)
        suspicious.append((path, ln, rest.strip()[:90], bool(has_nullchk)))
bad = [s for s in suspicious if not s[3]]
print("assigned-sites:", len(suspicious), " no-null-check-in-8-lines:", len(bad))
for b in bad:
    print(f"{b[0]}:{b[1]}: {b[2]}")
EOF

