import re, sys, os
# Heuristic: variable assigned from skb->data cast, then pskb_may_pull / skb_pull / skb_postpull_rcsum within following 12 lines, then deref of the same var AFTER the pull
import subprocess, os
out = subprocess.run(['grep','-rn','pskb_may_pull','net/'],capture_output=True,text=True).stdout
sites=[]
for line in out.splitlines():
    m=re.match(r'([^:]+):(\d+):(.*)',line)
    if m: sites.append((m.group(1),int(m.group(2)),m.group(3)))
res=[]
for p,ln,txt in sites:
    try: lines=open(p,errors='replace').read().splitlines()
    except: continue
    before='\n'.join(lines[max(0,ln-13):ln])  # 12 lines before pull
    after='\n'.join(lines[ln:ln+10])          # 9 lines after pull (including pull line)
    # find candidate pointer vars assigned from casts in before
    for m in re.finditer(r'(\w+)\s*=\s*\([^)]*\s*\*\s*\)\s*(?:skb->data|skb_network_header|skb_transport_header|skb_mac_header)\s*[\(+]', before):
        var=m.group(1)
        if re.search(r'\b'+var+r'\s*->', after) and 'skb_header_pointer' not in after:
            res.append((p,ln,var,txt.strip()[:100]))
    for m in re.finditer(r'(\w+)\s*=\s*skb_header_pointer\(', before):
        var=m.group(1)
        if re.search(r'\b'+var+r'\s*->', after):
            res.append((p,ln,var,'[hp] '+txt.strip()[:100]))
seen=set(); out2=[]
for r in res:
    k=(r[0],r[1],r[2])
    if k in seen: continue
    seen.add(k); out2.append(r)
print(len(out2))
for r in out2:
    print(f"{r[0]}:{r[1]}: var={r[2]} :: {r[3]}")
EOF

