python3 - << 'EOF'
import re, subprocess, os
out=subprocess.run(['grep','-rln','--include=*.c','pskb_may_pull','net/','drivers/net/'],capture_output=True,text=True).stdout
files=out.split()
pull_re=re.compile(r'\b(pskb_may_pull|__pskb_pull_tail|pskb_may_pull_reason|__pskb_pull|pskb_expand_head|skb_cow_head|skb_linearize)\s*\(')
ptr_re=re.compile(r'^\s*(?:const\s+)?(?:struct\s+)?[\w]+\s*\*+\s*(\w+)\s*=\s*(.*(?:skb_header_pointer|skb->data|skb_network_header|skb_transport_header|skb_mac_header|skb_tail_pointer|skb->head).*)$')
deref_re=re.compile(r'(\w+)->')
results=[]
for f in files:
    try: src=open(f,errors='replace').read().splitlines()
    except: continue
    # find function boundaries heuristically: track lines starting with '{' at col0 and '}'
    funcstart=0
    funcs=[]
    depth=0
    for i,l in enumerate(src):
        if l.startswith('{'): depth+=1; funcstart=i
        if l.startswith('}'):
            depth-=1
            if depth==0: funcs.append((funcstart,i))
    for (s,e) in funcs:
        body=src[s:e+1]
        pulls=[j for j,l in enumerate(body) if pull_re.search(l)]
        if not pulls: continue
        assigns={}
        for j,l in enumerate(body):
            m=ptr_re.match(l)
            if m:
                assigns.setdefault(m.group(1),[]).append((j,l.strip()))
        for name,occ in assigns.items():
            for (aj,aline) in occ:
                for p in pulls:
                    if aj < p:
                        # deref after pull?
                        after=body[p+1:]
                        if re.search(r'\b'+re.escape(name)+r'\s*->', ' '.join(after)) or re.search(r'\*\s*'+re.escape(name)+r'\b', ' '.join(after)):
                            results.append((f, s+aj+1, s+p+1, name, aline[:110], body[p][:90]))
                            break
for r in results:
    print('%s:%d (pull at %d) var=%s | %s || pull: %s'%r)
print('total', len(results))
EOF

